      "prompt": "write my commit message",
      "should_trigger": false,
      "assert": "Does not trigger for commit message drafting alone."
    }
  ]
}

#!/usr/bin/env python3
"""
Classify scope signals in a unified diff.

Usage:
    python3 scope_creep.py --repo . --intent "fix parser crash" --json
    python3 scope_creep.py --repo . --staged --json
    python3 scope_creep.py --repo . --base main --json
    python3 scope_creep.py --diff change.diff --intent "fix parser crash" --json

Python 3.11 stdlib only. Runs locally and never changes the target repository.
"""

import argparse
import collections
import json
import os
import re
import shlex
import subprocess
import sys


DEFAULT_HUNK_THRESHOLD = 80
STOP_WORDS = {
    "add", "branch", "bug", "change", "changes", "chore", "develop",
    "development", "feat", "feature", "fix", "fixed", "main", "master",
    "the", "this", "to", "update", "with",
}
CONFIG_EXTENSIONS = {".toml", ".yaml", ".yml"}
BUILD_FILES = {
    "cmakelists.txt", "docker-compose.yaml", "docker-compose.yml",
    "dockerfile", "makefile", "meson.build", "procfile",
}
SYMBOL_RE = re.compile(
    r"^\s*(?:(?:async\s+)?def\s+([A-Za-z_]\w*)|class\s+([A-Za-z_]\w*))"
)
HUNK_RE = re.compile(
    r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(.*)$"
)
REQUIREMENTS_RE = re.compile(r"^\s*([A-Za-z0-9][A-Za-z0-9_.-]*)")
JSON_PROPERTY_RE = re.compile(r'^\s*"([A-Za-z0-9@/_.-]+)"\s*:\s*(.+?)[,]?\s*$')
PYPROJECT_STRING_RE = re.compile(r'^\s*["\']([A-Za-z0-9][A-Za-z0-9_.-]*)[^"\']*["\']\s*,?\s*$')
PYPROJECT_ASSIGN_RE = re.compile(r"^\s*([A-Za-z0-9][A-Za-z0-9_.-]*)\s*=\s*(.+)$")


def clean_path(value):
    """Normalize a git header path without touching the filesystem."""
    value = value.strip()
    if "\t" in value:
        value = value.split("\t", 1)[0].rstrip()
    if value.startswith('"') and value.endswith('"'):
        try:
            value = json.loads(value)
        except json.JSONDecodeError:
            value = value[1:-1]
    if value in {"/dev/null", "dev/null"}:
        return None
    if value.startswith(("a/", "b/")):
        value = value[2:]
    return value


def new_file(old_path=None, new_path=None):
    return {
        "old_path": old_path,
        "new_path": new_path,
        "path": new_path or old_path or "unknown",
        "hunks": [],
    }


def parse_diff(text):
    """Parse the file and hunk structure needed by the classifiers."""
    files = []
    current = None
    hunk = None
    old_remaining = new_remaining = 0

    for raw in text.splitlines():
        if raw.startswith("diff --git "):
            try:
                parts = shlex.split(raw)
            except ValueError:
                parts = raw.split()
            old_path = clean_path(parts[2]) if len(parts) > 2 else None
            new_path = clean_path(parts[3]) if len(parts) > 3 else None
            current = new_file(old_path, new_path)
            files.append(current)
            hunk = None
            continue

        if current is None:
            if not raw.startswith("--- "):
                continue
            current = new_file()
            files.append(current)

        match = HUNK_RE.match(raw)
        if match:
            old_remaining = int(match.group(2) or "1")
            new_remaining = int(match.group(4) or "1")
            hunk = {"header": raw, "lines": []}
            current["hunks"].append(hunk)
            continue

        if hunk is not None:
            if not raw:
                continue
            marker = raw[0]
            if marker not in {" ", "+", "-"}:
                continue
            entry = {
                "marker": marker,
                "text": raw[1:],
                "index": len(hunk["lines"]),
            }
            hunk["lines"].append(entry)
            if marker != "+":
                old_remaining -= 1
            if marker != "-":
                new_remaining -= 1
            if old_remaining <= 0 and new_remaining <= 0:
                hunk = None
            continue

        if raw.startswith("--- ") and current["hunks"]:
            current = new_file()
            files.append(current)
        if raw.startswith("rename from "):
            current["old_path"] = clean_path(raw[len("rename from "):])
            current["path"] = current["new_path"] or current["old_path"]
            continue
        if raw.startswith("rename to "):
            current["new_path"] = clean_path(raw[len("rename to "):])
            current["path"] = current["new_path"] or current["old_path"]
            continue
        if raw.startswith("--- "):
            current["old_path"] = clean_path(raw[4:])
            current["path"] = current["new_path"] or current["old_path"] or "unknown"
            continue
        if raw.startswith("+++ "):
            current["new_path"] = clean_path(raw[4:])
            current["path"] = current["new_path"] or current["old_path"] or "unknown"
            continue

    return files


def changed_lines(file_change, marker):
    return [
        entry["text"]
        for hunk in file_change["hunks"]
        for entry in hunk["lines"]
        if entry["marker"] == marker
    ]


def tokenize(value):
    value = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", value)
    value = re.sub(r"[^A-Za-z0-9]+", " ", value).lower()
    return {
        token for token in value.split()
        if len(token) >= 3 and token not in STOP_WORDS
    }


def subsystem(path):
    parts = path.split("/")
    return parts[0] if len(parts) > 1 else "(root)"


def config_kind(path):
    normalized = path.lower()
    name = os.path.basename(normalized)
    extension = os.path.splitext(name)[1]
    if normalized.startswith(".github/"):
        return "ci"
    if name in BUILD_FILES or name.startswith("dockerfile."):
        return "build"
    if extension in CONFIG_EXTENSIONS:
        return "config"
    return None


def requirement_dependency(line):
    stripped = line.strip()
    if not stripped or stripped.startswith(("#", "-", ".")):
        return None
    match = REQUIREMENTS_RE.match(stripped)
    if not match:
        return None
    return match.group(1).lower().replace("_", "-"), stripped


def package_json_dependencies(file_change, marker):
    dependencies = []
    for hunk in file_change["hunks"]:
        in_dependencies = False
        for entry in hunk["lines"]:
            line = entry["text"]
            top_key = re.match(r'^\s{0,2}"([^"]+)"\s*:', line)
            if top_key:
                in_dependencies = top_key.group(1) in {
                    "dependencies", "devDependencies", "optionalDependencies",
                    "peerDependencies",
                }
                continue
            if entry["marker"] != marker or not in_dependencies:
                continue
            match = JSON_PROPERTY_RE.match(line)
            if match:
                dependencies.append((match.group(1).lower(), line.strip()))
    return dependencies


def pyproject_dependencies(file_change, marker):
    dependencies = []
    section = None
    in_project_list = False
    for hunk in file_change["hunks"]:
        for entry in hunk["lines"]:
            line = entry["text"]
            section_match = re.match(r"^\s*\[([^]]+)\]\s*$", line)
            if section_match:
                section = section_match.group(1).lower()
                in_project_list = False
                continue
            if section == "project" and re.match(r"^\s*dependencies\s*=\s*\[", line):
                in_project_list = True
                continue
            if in_project_list and "]" in line:
                in_project_list = False
            if entry["marker"] != marker:
                continue
            if in_project_list:
                match = PYPROJECT_STRING_RE.match(line)
                if match:
                    dependencies.append((match.group(1).lower().replace("_", "-"), line.strip()))
            elif section in {"tool.poetry.dependencies", "tool.poetry.group.dev.dependencies"}:
                match = PYPROJECT_ASSIGN_RE.match(line)
                if match and match.group(1).lower() != "python":
                    dependencies.append((match.group(1).lower().replace("_", "-"), line.strip()))
    return dependencies


def dependency_lines(file_change, marker):
    path = file_change["path"].lower()
    name = os.path.basename(path)
    if name.startswith("requirements") and name.endswith(".txt"):
        found = []
        for line in changed_lines(file_change, marker):
            parsed = requirement_dependency(line)
            if parsed:
                found.append(parsed)
        return found
    if name == "package.json":
        return package_json_dependencies(file_change, marker)
    if name == "pyproject.toml":
        return pyproject_dependencies(file_change, marker)
    return []


def find_new_dependencies(files):
    found = []
    for file_change in files:
        removed = {name for name, _line in dependency_lines(file_change, "-")}
        for name, line in dependency_lines(file_change, "+"):
            if name not in removed:
                found.append({"path": file_change["path"], "name": name, "line": line})
    unique = {(item["path"], item["name"]): item for item in found}
    return [unique[key] for key in sorted(unique)]


def declaration(entry):
    match = SYMBOL_RE.match(entry["text"])
    if not match:
        return None
    name = match.group(1) or match.group(2)
    if name.startswith("_"):
        return None
    kind = "function" if match.group(1) else "class"
    return {"kind": kind, "name": name, "entry": entry}


def find_api_renames(files):
    renames = []
    for file_change in files:
        for hunk in file_change["hunks"]:
            removed = [declaration(e) for e in hunk["lines"] if e["marker"] == "-"]
            added = [declaration(e) for e in hunk["lines"] if e["marker"] == "+"]
            removed = [item for item in removed if item]
            added = [item for item in added if item]
            used = set()
            for old in removed:
                candidates = [
                    (abs(old["entry"]["index"] - new["entry"]["index"]), index, new)
                    for index, new in enumerate(added)
                    if index not in used
                    and new["kind"] == old["kind"]
                    and new["name"] != old["name"]
                ]
                if not candidates:
                    continue
                distance, index, new = min(candidates)
                if distance > 12:
                    continue
                used.add(index)
                renames.append({
                    "path": file_change["path"],
                    "kind": old["kind"],
                    "from": old["name"],
                    "to": new["name"],
                    "hunk": hunk["header"],
                })
    return sorted(renames, key=lambda item: (item["path"], item["from"], item["to"]))


def lines_are_formatting_only(removed, added):
    if not removed or len(removed) != len(added):
        return False
    normalize = lambda line: re.sub(r"\s+", "", line)
    return [normalize(line) for line in removed] == [normalize(line) for line in added]


def classify(files, intent, hunk_threshold):
    intent_words = tokenize(intent)
    new_deps = find_new_dependencies(files)
    api_renames = find_api_renames(files)
    dep_paths = {item["path"] for item in new_deps}
    rename_paths = {item["path"] for item in api_renames}

    config_edits = []
    oversized = []
    formatting_only = []
    subsystems = collections.Counter()
    additions = deletions = 0
    file_metrics = {}

    for file_change in files:
        path = file_change["path"]
        subsystems[subsystem(path)] += 1
        added_lines = changed_lines(file_change, "+")
        removed_lines = changed_lines(file_change, "-")
        file_additions = len(added_lines)
        file_deletions = len(removed_lines)
        file_metrics[id(file_change)] = (file_additions, file_deletions)
        additions += file_additions
        deletions += file_deletions
        kind = config_kind(path)
        if kind:
            config_edits.append({
                "path": path,
                "kind": kind,
                "churn": file_additions + file_deletions,
            })
        if lines_are_formatting_only(removed_lines, added_lines):
            formatting_only.append(path)
        for hunk in file_change["hunks"]:
            churn = sum(1 for entry in hunk["lines"] if entry["marker"] in {"+", "-"})
            if churn > hunk_threshold:
                oversized.append({"path": path, "hunk": hunk["header"], "churn": churn})

    config_paths = {item["path"] for item in config_edits}
    oversized_paths = {item["path"] for item in oversized}
    formatting_paths = set(formatting_only)
    in_scope = []
    likely_creep = []

    for file_change in sorted(files, key=lambda item: item["path"]):
        path = file_change["path"]
        overlap = sorted(intent_words & tokenize(path))
        score = round(len(overlap) / max(1, len(intent_words)), 3)
        signals = []
        if path in dep_paths:
            signals.append("new_dependency")
        if path in rename_paths:
            signals.append("public_api_rename")
        if path in config_paths:
            signals.append("config_edit")
        if path in oversized_paths:
            signals.append("oversized_hunk")
        if path in formatting_paths:
            signals.append("formatting_only")

        additions_for_file, deletions_for_file = file_metrics[id(file_change)]
        reasons = []
        if overlap:
            reasons.append("intent/path overlap: %s" % ", ".join(overlap))
        elif intent_words:
            reasons.append("no intent/path keyword overlap")
        else:
            reasons.append("intent has no usable keywords")
        reasons.extend(signal.replace("_", " ") for signal in signals)
        item = {
            "path": path,
            "subsystem": subsystem(path),
            "relatedness": score,
            "overlap": overlap,
            "signals": signals,
            "reasons": reasons,
            "additions": additions_for_file,
            "deletions": deletions_for_file,
        }
        (in_scope if overlap else likely_creep).append(item)

    return {
        "intent": intent,
        "in_scope": in_scope,
        "likely_creep": likely_creep,
        "new_deps": new_deps,
        "api_renames": api_renames,
        "config_edits": sorted(config_edits, key=lambda item: item["path"]),
        "stats": {
            "files_touched": len(files),
            "additions": additions,
            "deletions": deletions,
            "subsystems": dict(sorted(subsystems.items())),
            "oversized_hunks": oversized,
            "formatting_only_files": sorted(formatting_only),
            "hunk_threshold": hunk_threshold,
        },
    }


def run_git(repo, args):
    result = subprocess.run(
        ["git", "-C", repo, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or "git command failed")
    return result.stdout


def read_diff(args):
    if args.diff == "-":
        return sys.stdin.read()
    if args.diff:
        with open(args.diff, encoding="utf-8", errors="replace") as handle:
            return handle.read()
    command = ["diff", "--no-ext-diff", "--no-textconv", "--unified=3"]
    if args.staged:
        command.append("--cached")
    elif args.base:
        command.append("%s...HEAD" % args.base)
    command.append("--")
    return run_git(args.repo, command)


def fallback_intent(repo):
    try:
        branch = run_git(repo, ["branch", "--show-current"]).strip()
    except RuntimeError:
        branch = ""
    return branch or "detached HEAD"


def print_human(report):
    stats = report["stats"]
    print("SCOPE REPORT")
    print("intent: %s" % report["intent"])
    print(
        "files: %(files_touched)d  additions: %(additions)d  deletions: %(deletions)d"
        % stats
    )
    print("subsystems: %s" % (", ".join(
        "%s=%d" % item for item in stats["subsystems"].items()
    ) or "none"))
    print("in scope: %d" % len(report["in_scope"]))
    for item in report["in_scope"]:
        print("  KEEP? %s (%s)" % (item["path"], "; ".join(item["reasons"])))
    print("likely creep: %d" % len(report["likely_creep"]))
    for item in report["likely_creep"]:
        print("  SPLIT OR JUSTIFY: %s (%s)" % (item["path"], "; ".join(item["reasons"])))


def build_parser():
    parser = argparse.ArgumentParser(description="Detect scope signals in a git unified diff.")
    parser.add_argument("--repo", default=".", help="Target git repository (default: current directory).")
    parser.add_argument("--diff", help="Read a unified diff from a file, or '-' for stdin.")
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument("--staged", action="store_true", help="Analyze the staged diff.")
    modes.add_argument("--base", help="Analyze BASE...HEAD for a branch diff.")
    parser.add_argument("--intent", help="One-line intent; defaults to the current branch name.")
    parser.add_argument(
        "--hunk-threshold",
        type=int,
        default=DEFAULT_HUNK_THRESHOLD,
        help="Flag hunks with churn above this value (default: 80).",
    )
    parser.add_argument("--json", action="store_true", help="Emit the full JSON report.")
    return parser


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.diff and (args.staged or args.base):
        parser.error("--diff cannot be combined with --staged or --base")
    if args.hunk_threshold < 1:
        parser.error("--hunk-threshold must be at least 1")

    try:
        diff_text = read_diff(args)
        intent = args.intent.strip() if args.intent and args.intent.strip() else fallback_intent(args.repo)
        report = classify(parse_diff(diff_text), intent, args.hunk_threshold)
    except (OSError, RuntimeError, subprocess.TimeoutExpired) as error:
        print("scope_creep.py: error: %s" % error, file=sys.stderr)
        return 2

    if args.json:
        json.dump(report, sys.stdout, indent=2, sort_keys=True)
        sys.stdout.write("\n")
    else:
        print_human(report)
    return 0


if __name__ == "__main__":
    sys.exit(main())

from fastapi import FastAPI, UploadFile, File, HTTPException, Form
from fastapi.responses import StreamingResponse, FileResponse
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from typing import Optional, List, Dict
import time
import uuid
import zipfile
import io
import os
import json
import asyncio
import tempfile
import shutil
import re
import logging
import traceback
from adk_optimizer import SkillOptimizer

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

MAX_UPLOAD_SIZE = 10 * 1024 * 1024  # 10 MB total
MAX_FILE_SIZE = 1 * 1024 * 1024     # 1 MB per file
MAX_FILE_COUNT = 50
SESSION_TTL = 3600  # 1 hour
ALLOWED_EXTENSIONS = {
    ".md", ".txt", ".json", ".yaml", ".yml", ".py", ".js", ".ts",
    ".html", ".css", ".xml", ".toml", ".cfg", ".ini", ".sh",
}

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

sessions: Dict[str, dict] = {}


class AnalyzeRequest(BaseModel):
    session_id: str
    gemini_api_key: str


class SessionConfig(BaseModel):
    session_id: str
    scenarios: List[dict]
    evals: List[dict]


class RegenerateRequest(BaseModel):
    session_id: str
    gemini_api_key: str


class StartRequest(BaseModel):
    gemini_api_key: str
    max_rounds: Optional[int] = Field(default=20, gt=0, le=50)


def parse_skill_frontmatter(content: str) -> dict:
    """Parse YAML frontmatter from SKILL.md"""
    if not content.startswith("---"):
        return {}
    try:
        parts = content.split("---", 2)
        if len(parts) < 3:
            return {}
        frontmatter = parts[1].strip()
        metadata = {}
        for line in frontmatter.split("\n"):
            line = line.strip()
            if ":" in line and not line.startswith(" "):
                key, value = line.split(":", 1)
                metadata[key.strip()] = value.strip().strip('"')
        return metadata
    except Exception:
        return {}


def create_session_from_files(skill_files: dict, file_list: list) -> dict:
    """Create a session dict from skill files"""
    skill_md = None
    for name, content in skill_files.items():
        if name.endswith("SKILL.md"):
            skill_md = content
            break
    if not skill_md:
        raise HTTPException(status_code=400, detail="No SKILL.md found")
    metadata = parse_skill_frontmatter(skill_md)
    session_id = str(uuid.uuid4())
    sessions[session_id] = {
        "skill_files": skill_files,
        "file_list": file_list,
        "metadata": metadata,
        "status": "uploaded",
        "scenarios": None,
        "evals": None,
        "experiments": [],
        "changelog": [],
        "current_skill_md": skill_md,
        "original_skill_md": skill_md,
        "created_at": time.time(),
    }
    return {"session_id": session_id, "file_list": file_list, "metadata": metadata}


def _is_allowed_file(name: str) -> bool:
    """Check if file extension is in the allowed text-file list."""
    _, ext = os.path.splitext(name)
    return ext.lower() in ALLOWED_EXTENSIONS


def _is_safe_path(name: str) -> bool:
    """Reject path traversal attempts."""
    return ".." not in name and not os.path.isabs(name)


@app.post("/api/upload")
async def upload_skill(file: UploadFile = File(...)):
    """Accept zip file or multiple files, extract, return file list + parsed SKILL.md metadata"""
    if not file.filename.endswith(".zip"):
        raise HTTPException(status_code=400, detail="Only .zip files are accepted")
    content = await file.read()
    if len(content) > MAX_UPLOAD_SIZE:
        raise HTTPException(status_code=413, detail=f"Upload exceeds {MAX_UPLOAD_SIZE // (1024*1024)}MB limit")
    try:
        with zipfile.ZipFile(io.BytesIO(content)) as zf:
            skill_files = {}
            file_list = []
            for name in zf.namelist():
                if name.endswith("/") or name.startswith("__MACOSX") or "/.DS_Store" in name or name.endswith(".DS_Store"):
                    continue
                if not _is_safe_path(name):
                    logger.warning(f"Skipping unsafe zip entry: {name}")
                    continue
                if not _is_allowed_file(name):
                    logger.info(f"Skipping non-text file: {name}")
                    continue
                raw = zf.read(name)
                if len(raw) > MAX_FILE_SIZE:
                    logger.warning(f"Skipping oversized file: {name} ({len(raw)} bytes)")
                    continue
                if len(file_list) >= MAX_FILE_COUNT:
                    logger.warning("Max file count reached, skipping remaining entries")
                    break
                file_content = raw.decode("utf-8", errors="ignore")
                skill_files[name] = file_content
                file_list.append(name)

            # Normalize paths: strip common prefix directory
            if file_list:
                common = os.path.commonpath(file_list)
                if common and common != file_list[0]:
                    skill_files = {os.path.relpath(k, common): v for k, v in skill_files.items()}
                    file_list = [os.path.relpath(f, common) for f in file_list]

            return create_session_from_files(skill_files, file_list)
    except zipfile.BadZipFile:
        raise HTTPException(status_code=400, detail="Invalid zip file")
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Upload error: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail="Error processing file")


@app.post("/api/upload-files")
async def upload_files(files: List[UploadFile] = File(...)):
    """Accept multiple files (folder upload via webkitdirectory)"""
    if len(files) > MAX_FILE_COUNT:
        raise HTTPException(status_code=413, detail=f"Too many files (max {MAX_FILE_COUNT})")
    skill_files = {}
    file_list = []
    total_size = 0
    for f in files:
        if f.filename.startswith(".") or "/.DS_Store" in (f.filename or "") or "__MACOSX" in (f.filename or ""):
            continue
        name = f.filename or "unknown"
        if not _is_safe_path(name):
            logger.warning(f"Skipping unsafe path: {name}")
            continue
        if not _is_allowed_file(name):
            logger.info(f"Skipping non-text file: {name}")
            continue
        content = await f.read()
        total_size += len(content)
        if total_size > MAX_UPLOAD_SIZE:
            raise HTTPException(status_code=413, detail=f"Total upload exceeds {MAX_UPLOAD_SIZE // (1024*1024)}MB limit")
        if len(content) > MAX_FILE_SIZE:
            logger.warning(f"Skipping oversized file: {name} ({len(content)} bytes)")
            continue
        skill_files[name] = content.decode("utf-8", errors="ignore")
        file_list.append(name)

    # Normalize paths: strip common prefix directory
    if file_list:
        common = os.path.commonpath(file_list)
        if common and common != file_list[0]:
            skill_files = {os.path.relpath(k, common): v for k, v in skill_files.items()}
            file_list = [os.path.relpath(f, common) for f in file_list]

    return create_session_from_files(skill_files, file_list)


@app.post("/api/analyze")
async def analyze_skill(request: AnalyzeRequest):
    """Generate scenarios + evals using Gemini"""
    if request.session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[request.session_id]
    try:
        optimizer = SkillOptimizer(api_key=request.gemini_api_key)
        analysis = await optimizer.analyze_skill(session["skill_files"])
        session["scenarios"] = analysis["scenarios"]
        session["evals"] = analysis["evals"]
        session["status"] = "analyzed"
        return {"scenarios": analysis["scenarios"], "evals": analysis["evals"]}
    except Exception as e:
        logger.error(f"Analysis error: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail="Analysis failed. Check your API key and try again.")


@app.post("/api/regenerate")
async def regenerate_config(request: RegenerateRequest):
    """Regenerate scenarios/evals for a session"""
    analyze_req = AnalyzeRequest(session_id=request.session_id, gemini_api_key=request.gemini_api_key)
    return await analyze_skill(analyze_req)


@app.post("/api/update-config")
async def update_config(config: SessionConfig):
    """Save user's selected/edited scenarios + evals"""
    if config.session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[config.session_id]
    session["scenarios"] = config.scenarios
    session["evals"] = config.evals
    session["status"] = "configured"
    return {"status": "ok"}


@app.get("/api/stream/{session_id}")
async def stream_progress(session_id: str):
    """SSE endpoint streaming optimization progress"""
    if session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[session_id]

    async def event_generator():
        if "event_queue" not in session:
            session["event_queue"] = asyncio.Queue()
        queue = session["event_queue"]
        try:
            while True:
                event = await queue.get()
                if event is None:
                    break
                yield f"data: {json.dumps(event)}\n\n"
        except asyncio.CancelledError:
            pass
        finally:
            if "event_queue" in session:
                del session["event_queue"]

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "Connection": "keep-alive"},
    )


@app.post("/api/start/{session_id}")
async def start_optimization(session_id: str, request: StartRequest):
    """Start optimization in background task"""
    if session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[session_id]
    if not session.get("scenarios") or not session.get("evals"):
        raise HTTPException(status_code=400, detail="Must configure scenarios and evals first")
    if session.get("status") == "running":
        raise HTTPException(status_code=400, detail="Optimization already running")

    session["status"] = "running"
    session["stop_requested"] = False
    # Pre-create the event queue so events aren't lost before SSE connects
    session["event_queue"] = asyncio.Queue()
    gemini_key = request.gemini_api_key

    async def run_optimization():
        logger.info(f"Starting optimization for session {session_id}")
        optimizer = SkillOptimizer(api_key=gemini_key)

        async def callback(event):
            logger.info(f"Callback event: {event['type']}")
            if "event_queue" in session:
                await session["event_queue"].put(event)
            if event["type"] == "baseline":
                session["experiments"].append({
                    "experiment_id": 0,
                    "pass_rate": event["data"].get("score", 0),
                    "status": "baseline",
                    "per_eval": event["data"].get("per_eval", []),
                })
            elif event["type"] == "experiment_result":
                session["experiments"].append({
                    "experiment_id": event["data"].get("round", len(session["experiments"])),
                    "pass_rate": event["data"].get("score", 0),
                    "status": "keep" if event["data"].get("kept") else "discard",
                    "per_eval": event["data"].get("per_eval", []),
                    "description": event["data"].get("description", ""),
                    "strategy": event["data"].get("strategy", ""),
                })
            elif event["type"] == "complete":
                session["status"] = "complete"
                data = event["data"]
                ml = data.get("mutation_log", [])
                # Transform to match frontend ResultsStep expectations
                session["final_result"] = {
                    "baseline_score": data.get("baseline_score", 0),
                    "final_score": data.get("final_score", 0),
                    "improved_skill_md": data.get("improved_skill_md", ""),
                    "original_skill_md": session.get("original_skill_md", ""),
                    "score_history": data.get("score_history", []),
                    "experiments_run": len(ml),
                    "kept": sum(1 for m in ml if m.get("kept")),
                    "discarded": sum(1 for m in ml if not m.get("kept")),
                    "changelog": [
                        {
                            "description": m.get("description", m.get("diagnosis", "")),
                            "reasoning": m.get("diagnosis", ""),
                            "status": "keep" if m.get("kept") else "discard",
                            "score_before": m.get("score_before", 0),
                            "score_after": m.get("score_after", 0),
                            "strategy": m.get("strategy_type", ""),
                        }
                        for m in ml
                    ],
                    "mutation_log": ml,
                    "strategy_stats": data.get("strategy_stats", {}),
                }
                session["current_skill_md"] = data.get("improved_skill_md", "")
                if "event_queue" in session:
                    await session["event_queue"].put(None)

        try:
            result = await optimizer.optimize(
                skill_files=session["skill_files"],
                scenarios=session["scenarios"],
                evals=session["evals"],
                max_rounds=request.max_rounds,
                callback=callback,
            )
            logger.info(f"Optimization complete: {result['baseline_score']}% -> {result['final_score']}%")
            # Don't overwrite final_result if callback already set it with transformed data
            if not session.get("final_result"):
                ml = result.get("mutation_log", [])
                session["final_result"] = {
                    "baseline_score": result.get("baseline_score", 0),
                    "final_score": result.get("final_score", 0),
                    "improved_skill_md": result.get("improved_skill_md", ""),
                    "original_skill_md": session.get("original_skill_md", ""),
                    "score_history": result.get("score_history", []),
                    "experiments_run": len(ml),
                    "kept": sum(1 for m in ml if m.get("kept")),
                    "discarded": sum(1 for m in ml if not m.get("kept")),
                    "changelog": [
                        {
                            "description": m.get("description", m.get("diagnosis", "")),
                            "reasoning": m.get("diagnosis", ""),
                            "status": "keep" if m.get("kept") else "discard",
                            "score_before": m.get("score_before", 0),
                            "score_after": m.get("score_after", 0),
                            "strategy": m.get("strategy_type", ""),
                        }
                        for m in ml
                    ],
                    "mutation_log": ml,
                }
            session["current_skill_md"] = result["improved_skill_md"]
            session["status"] = "complete"
        except Exception as e:
            logger.error(f"Optimization error: {traceback.format_exc()}")
            session["status"] = "error"
            session["error"] = str(e)
            if "event_queue" in session:
                await session["event_queue"].put({"type": "error", "data": {"message": str(e)}})
                await session["event_queue"].put(None)

    asyncio.create_task(run_optimization())
    return {"status": "started"}


@app.post("/api/stop/{session_id}")
async def stop_optimization(session_id: str):
    """Stop optimization"""
    if session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[session_id]
    session["stop_requested"] = True
    session["status"] = "stopped"
    if "event_queue" in session:
        await session["event_queue"].put(None)
    return {"status": "stopped"}


@app.get("/api/download/{session_id}")
async def download_skill(session_id: str):
    """Download improved skill as zip"""
    if session_id not in sessions:
        raise HTTPException(status_code=404, detail="Session not found")
    session = sessions[session_id]
    if not session.get("current_skill_md"):
        raise HTTPException(status_code=400, detail="No improved skill available")
    temp_dir = tempfile.mkdtemp()
    zip_path = os.path.join(temp_dir, "improved_skill.zip")
    try:
        with zipfile.ZipFile(zip_path, "w") as zf:
            for filename, content in session["skill_files"].items():
                if filename.endswith("SKILL.md"):
                    zf.writestr(filename, session["current_skill_md"])
                else:
                    zf.writestr(filename, content)
            if session.get("final_result"):
                changelog_content = json.dumps(session["final_result"]["changelog"], indent=2)
                zf.writestr("CHANGELOG.json", changelog_content)
        return FileResponse(zip_path, media_type="application/zip", filename="improved_skill.zip")
    finally:
        asyncio.create_task(cleanup_temp_dir(temp_dir))


async def cleanup_temp_dir(temp_dir: str):
    await asyncio.sleep(60)
    try:
        shutil.rmtree(temp_dir)
    except Exception:
        pass


@app.get("/api/examples")
async def list_examples():
    """List available example skills"""
    # Sibling skills in this repo double as examples — the app demos on real
    # skills (e.g. project-graveyard), not on toy prompt files.
    examples_dir = os.path.join(os.path.dirname(__file__), "..", "..")
    examples = []
    if os.path.exists(examples_dir):
        for name in sorted(os.listdir(examples_dir)):
            skill_dir = os.path.join(examples_dir, name)
            skill_md_path = os.path.join(skill_dir, "SKILL.md")
            if os.path.isdir(skill_dir) and os.path.exists(skill_md_path):
                with open(skill_md_path, "r") as f:
                    content = f.read()
                metadata = parse_skill_frontmatter(content)
                examples.append({"name": metadata.get("name", name), "description": metadata.get("description", ""), "path": name})
    return {"examples": examples}


@app.post("/api/examples/{example_name}/load")
async def load_example(example_name: str):
    """Load an example skill as if it were uploaded"""
    if not re.fullmatch(r"[a-zA-Z0-9_-]+", example_name):
        raise HTTPException(status_code=400, detail="Invalid example name")
    examples_dir = os.path.realpath(os.path.join(os.path.dirname(__file__), "..", ".."))
    skill_dir = os.path.realpath(os.path.join(examples_dir, example_name))
    if not skill_dir.startswith(examples_dir + os.sep):
        raise HTTPException(status_code=400, detail="Invalid example name")
    if not os.path.isdir(skill_dir):
        raise HTTPException(status_code=404, detail="Example skill not found")
    skill_files = {}
    file_list = []
    for root, dirs, files in os.walk(skill_dir):
        for fname in files:
            if fname.startswith("."):
                continue
            full_path = os.path.join(root, fname)
            rel_path = os.path.relpath(full_path, skill_dir)
            with open(full_path, "r") as f:
                skill_files[rel_path] = f.read()
            file_list.append(rel_path)
    return create_session_from_files(skill_files, file_list)


