export default function Home() {
  const [currentStep, setCurrentStep] = useState(1);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [apiKey, setApiKey] = useState("");
  const [metadata, setMetadata] = useState<any>(null);
  const [scenarios, setScenarios] = useState<any[]>([]);
  const [evals, setEvals] = useState<any[]>([]);
  const [finalResult, setFinalResult] = useState<any>(null);

  const handleUploadComplete = (
    sid: string,
    key: string,
    meta: any,
    initialScenarios: any[],
    initialEvals: any[]
  ) => {
    setSessionId(sid);
    setApiKey(key);
    setMetadata(meta);
    setScenarios(initialScenarios);
    setEvals(initialEvals);
    setCurrentStep(2);
  };

  const handleConfigComplete = () => {
    setCurrentStep(3);
  };

  const handleOptimizationComplete = (result: any) => {
    setFinalResult(result);
    setCurrentStep(4);
  };

  const handleStartOver = () => {
    setCurrentStep(1);
    setSessionId(null);
    setApiKey("");
    setMetadata(null);
    setScenarios([]);
    setEvals([]);
    setFinalResult(null);
  };

  return (
    <main className="min-h-screen p-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-5xl font-bold mb-4">
            <span className="gradient-text">Self-Improving</span> Agent Skills
          </h1>
          <p className="text-zinc-400 dark:text-zinc-400 text-zinc-600 text-lg">
            Powered by Google ADK multi-agent system and Gemini
          </p>
          <div className="flex items-center justify-center gap-2 mt-3">
            <span className="px-3 py-1 bg-blue-500/10 text-blue-400 dark:text-blue-400 text-blue-600 rounded-full text-xs font-medium border border-blue-500/20">Google ADK</span>
            <span className="px-3 py-1 bg-violet-500/10 text-violet-400 dark:text-violet-400 text-violet-600 rounded-full text-xs font-medium border border-violet-500/20">Gemini</span>
            <span className="px-3 py-1 bg-emerald-500/10 text-emerald-400 dark:text-emerald-400 text-emerald-600 rounded-full text-xs font-medium border border-emerald-500/20">Multi-Agent</span>
          </div>
        </div>

        <StepIndicator currentStep={currentStep} />

        <div className="mt-12">
          {currentStep === 1 && (
            <UploadStep onComplete={handleUploadComplete} />
          )}

          {currentStep === 2 && sessionId && (
            <ConfigStep
              sessionId={sessionId}
              apiKey={apiKey}
              scenarios={scenarios}
              evals={evals}
              onScenariosChange={setScenarios}
              onEvalsChange={setEvals}
              onComplete={handleConfigComplete}
            />
          )}

          {currentStep === 3 && sessionId && (
            <RunningStep
              sessionId={sessionId}
              apiKey={apiKey}
              scenarios={scenarios}
              evals={evals}
              onComplete={handleOptimizationComplete}
            />
          )}

          {currentStep === 4 && finalResult && (
            <ResultsStep
              result={finalResult}
              sessionId={sessionId!}
              onStartOver={handleStartOver}
            />
          )}
        </div>
      </div>
    </main>
  );
}

"use client";

import { useState } from "react";
import { CheckSquare, Square, Plus, X, RefreshCw, ArrowRight } from "lucide-react";

interface ConfigStepProps {
  sessionId: string;
  apiKey: string;
  scenarios: any[];
  evals: any[];
  onScenariosChange: (scenarios: any[]) => void;
  onEvalsChange: (evals: any[]) => void;
  onComplete: () => void;
}

export default function ConfigStep({
  sessionId,
  apiKey,
  scenarios: initialScenarios,
  evals: initialEvals,
  onScenariosChange,
  onEvalsChange,
  onComplete,
}: ConfigStepProps) {
  const [scenarios, setScenarios] = useState(
    initialScenarios.map((s) => ({ ...s, selected: true, editing: false }))
  );
  const [evals, setEvals] = useState(
    initialEvals.map((e) => ({ ...e, selected: true, editing: false }))
  );
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [showAddScenario, setShowAddScenario] = useState(false);
  const [showAddEval, setShowAddEval] = useState(false);

  const handleScenarioToggle = (id: number) => {
    setScenarios((prev) =>
      prev.map((s) => (s.id === id ? { ...s, selected: !s.selected } : s))
    );
  };

  const handleEvalToggle = (id: number) => {
    setEvals((prev) =>
      prev.map((e) => (e.id === id ? { ...e, selected: !e.selected } : e))
    );
  };

  const handleScenarioEdit = (id: number, field: string, value: string) => {
    setScenarios((prev) =>
      prev.map((s) => (s.id === id ? { ...s, [field]: value } : s))
    );
  };

  const handleEvalEdit = (id: number, field: string, value: string) => {
    setEvals((prev) =>
      prev.map((e) => (e.id === id ? { ...e, [field]: value } : e))
    );
  };

  const handleDeleteScenario = (id: number) => {
    setScenarios((prev) => prev.filter((s) => s.id !== id));
  };

  const handleDeleteEval = (id: number) => {
    setEvals((prev) => prev.filter((e) => e.id !== id));
  };

  const handleAddScenario = () => {
    const newId = Math.max(...scenarios.map((s) => s.id), 0) + 1;
    setScenarios((prev) => [
      ...prev,
      {
        id: newId,
        description: "New scenario",
        input: "",
        selected: true,
        editing: true,
      },
    ]);
    setShowAddScenario(false);
  };

  const handleAddEval = () => {
    const newId = Math.max(...evals.map((e) => e.id), 0) + 1;
    setEvals((prev) => [
      ...prev,
      {
        id: newId,
        name: "New criterion",
        question: "",
        pass_condition: "",
        fail_condition: "",
        selected: true,
        editing: true,
      },
    ]);
    setShowAddEval(false);
  };

  const handleRegenerate = async () => {
    setIsRegenerating(true);

    try {
      const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891";
      const response = await fetch(`${API_BASE}/api/regenerate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: sessionId, gemini_api_key: apiKey }),
      });

      if (!response.ok) {
        throw new Error("Regeneration failed");
      }

      const data = await response.json();
      setScenarios(data.scenarios.map((s: any) => ({ ...s, selected: true })));
      setEvals(data.evals.map((e: any) => ({ ...e, selected: true })));
    } catch (error) {
      alert("Failed to regenerate. Please try again.");
    } finally {
      setIsRegenerating(false);
    }
  };

  const handleContinue = async () => {
    const selectedScenarios = scenarios.filter((s) => s.selected);
    const selectedEvals = evals.filter((e) => e.selected);

    if (selectedScenarios.length === 0 || selectedEvals.length === 0) {
      alert("Please select at least one scenario and one evaluation criterion");
      return;
    }

    try {
      const API_BASE2 = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891";
      const response = await fetch(`${API_BASE2}/api/update-config`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          session_id: sessionId,
          scenarios: selectedScenarios,
          evals: selectedEvals,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to save configuration");
      }

      onScenariosChange(selectedScenarios);
      onEvalsChange(selectedEvals);
      onComplete();
    } catch (error) {
      alert("Failed to save configuration. Please try again.");
    }
  };

  const selectedScenarioCount = scenarios.filter((s) => s.selected).length;
  const selectedEvalCount = evals.filter((e) => e.selected).length;

  return (
    <div className="max-w-5xl mx-auto space-y-8">
      <div className="glass rounded-2xl p-8">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold">Test Scenarios</h2>
            <span className="px-3 py-1 bg-violet-500/20 text-violet-400 rounded-full text-sm font-medium">
              {selectedScenarioCount} selected
            </span>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setShowAddScenario(true)}
              className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 rounded-lg transition-colors flex items-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Add
            </button>
            <button
              onClick={handleRegenerate}
              disabled={isRegenerating}
              className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 rounded-lg transition-colors flex items-center gap-2"
            >
              <RefreshCw className={`w-4 h-4 ${isRegenerating ? "animate-spin" : ""}`} />
              Regenerate
            </button>
          </div>
        </div>

        <div className="space-y-4">
          {showAddScenario && (
            <div className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg">
              <button
                onClick={handleAddScenario}
                className="w-full py-3 border-2 border-dashed border-zinc-700 rounded-lg hover:border-violet-500 transition-colors text-zinc-400 hover:text-white"
              >
                Click to add scenario
              </button>
            </div>
          )}

          {scenarios.map((scenario) => (
            <div
              key={scenario.id}
              className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg hover:border-zinc-700 transition-colors"
            >
              <div className="flex items-start gap-3">
                <button
                  onClick={() => handleScenarioToggle(scenario.id)}
                  className="mt-1 text-violet-500 hover:text-violet-400"
                >
                  {scenario.selected ? (
                    <CheckSquare className="w-5 h-5" />
                  ) : (
                    <Square className="w-5 h-5" />
                  )}
                </button>

                <div className="flex-1 space-y-2">
                  <input
                    type="text"
                    value={scenario.description}
                    onChange={(e) =>
                      handleScenarioEdit(scenario.id, "description", e.target.value)
                    }
                    className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-violet-500"
                  />
                  <textarea
                    value={scenario.input}
                    onChange={(e) =>
                      handleScenarioEdit(scenario.id, "input", e.target.value)
                    }
                    rows={3}
                    placeholder="Test input..."
                    className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-violet-500 resize-none"
                  />
                </div>

                <button
                  onClick={() => handleDeleteScenario(scenario.id)}
                  className="mt-1 text-zinc-500 hover:text-red-400 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="glass rounded-2xl p-8">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold">Evaluation Criteria</h2>
            <span className="px-3 py-1 bg-violet-500/20 text-violet-400 rounded-full text-sm font-medium">
              {selectedEvalCount} selected
            </span>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setShowAddEval(true)}
              className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 rounded-lg transition-colors flex items-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Add
            </button>
          </div>
        </div>

        <div className="space-y-4">
          {showAddEval && (
            <div className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg">
              <button
                onClick={handleAddEval}
                className="w-full py-3 border-2 border-dashed border-zinc-700 rounded-lg hover:border-violet-500 transition-colors text-zinc-400 hover:text-white"
              >
                Click to add criterion
              </button>
            </div>
          )}

          {evals.map((evalItem) => (
            <div
              key={evalItem.id}
              className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg hover:border-zinc-700 transition-colors"
            >
              <div className="flex items-start gap-3">
                <button
                  onClick={() => handleEvalToggle(evalItem.id)}
                  className="mt-1 text-violet-500 hover:text-violet-400"
                >
                  {evalItem.selected ? (
                    <CheckSquare className="w-5 h-5" />
                  ) : (
                    <Square className="w-5 h-5" />
                  )}
                </button>

                <div className="flex-1 space-y-2">
                  <input
                    type="text"
                    value={evalItem.name}
                    onChange={(e) =>
                      handleEvalEdit(evalItem.id, "name", e.target.value)
                    }
                    className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-violet-500 font-semibold"
                  />
                  <input
                    type="text"
                    value={evalItem.question}
                    onChange={(e) =>
                      handleEvalEdit(evalItem.id, "question", e.target.value)
                    }
                    placeholder="Yes/no question..."
                    className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-violet-500"
                  />
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      type="text"
                      value={evalItem.pass_condition}
                      onChange={(e) =>
                        handleEvalEdit(evalItem.id, "pass_condition", e.target.value)
                      }
                      placeholder="Pass condition..."
                      className="px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-green-500 text-sm"
                    />
                    <input
                      type="text"
                      value={evalItem.fail_condition}
                      onChange={(e) =>
                        handleEvalEdit(evalItem.id, "fail_condition", e.target.value)
                      }
                      placeholder="Fail condition..."
                      className="px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg focus:outline-none focus:border-red-500 text-sm"
                    />
                  </div>
                </div>

                <button
                  onClick={() => handleDeleteEval(evalItem.id)}
                  className="mt-1 text-zinc-500 hover:text-red-400 transition-colors"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <button
        onClick={handleContinue}
        disabled={selectedScenarioCount === 0 || selectedEvalCount === 0}
        className={`
          w-full py-4 rounded-xl font-semibold transition-all flex items-center justify-center gap-2
          ${
            selectedScenarioCount > 0 && selectedEvalCount > 0
              ? "gradient-bg hover:scale-105"
              : "bg-zinc-800 text-zinc-500 cursor-not-allowed"
          }
        `}
      >
        Start Optimization
        <ArrowRight className="w-5 h-5" />
      </button>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Download, RotateCcw, TrendingUp, CheckCircle, XCircle } from "lucide-react";
import { diffLines, Change } from "diff";

interface ResultsStepProps {
  result: any;
  sessionId: string;
  onStartOver: () => void;
}

export default function ResultsStep({
  result,
  sessionId,
  onStartOver,
}: ResultsStepProps) {
  const [showDiff, setShowDiff] = useState(false);

  const handleDownload = async () => {
    try {
      const response = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891"}/api/download/${sessionId}`
      );

      if (!response.ok) {
        throw new Error("Download failed");
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "improved_skill.zip";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      alert("Download failed. Please try again.");
    }
  };

  const improvementPercent =
    result.final_score - result.baseline_score;

  const topChanges = result.changelog
    ?.filter((c: any) => c.status === "keep")
    .slice(0, 5) || [];

  const diff = diffLines(
    result.original_skill_md || "",
    result.improved_skill_md || ""
  );

  return (
    <div className="max-w-6xl mx-auto space-y-8">
      <div className="glass rounded-2xl p-12 text-center">
        <div className="inline-flex items-center gap-6 mb-6">
          <div>
            <div className="text-5xl font-bold text-zinc-400">
              {result.baseline_score.toFixed(0)}%
            </div>
            <div className="text-sm text-zinc-500 mt-1">Baseline</div>
          </div>

          <TrendingUp className="w-12 h-12 text-violet-500" />

          <div>
            <div className="text-5xl font-bold gradient-text">
              {result.final_score.toFixed(0)}%
            </div>
            <div className="text-sm text-zinc-500 mt-1">Final</div>
          </div>
        </div>

        <div className="text-3xl font-bold text-green-400 mb-2">
          +{improvementPercent.toFixed(1)}%
        </div>
        <p className="text-zinc-400">Improvement achieved</p>
      </div>

      <div className="grid grid-cols-3 gap-6">
        <div className="glass rounded-xl p-6 text-center">
          <div className="text-3xl font-bold mb-2">
            {result.experiments_run}
          </div>
          <div className="text-sm text-zinc-400">Experiments Run</div>
        </div>

        <div className="glass rounded-xl p-6 text-center">
          <div className="text-3xl font-bold text-green-400 mb-2">
            {result.kept}
          </div>
          <div className="text-sm text-zinc-400">Changes Kept</div>
        </div>

        <div className="glass rounded-xl p-6 text-center">
          <div className="text-3xl font-bold text-red-400 mb-2">
            {result.discarded}
          </div>
          <div className="text-sm text-zinc-400">Changes Discarded</div>
        </div>
      </div>

      {topChanges.length > 0 && (
        <div className="glass rounded-2xl p-8">
          <h3 className="text-2xl font-bold mb-6">Top Changes</h3>
          <div className="space-y-4">
            {topChanges.map((change: any, idx: number) => (
              <div
                key={idx}
                className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg"
              >
                <div className="flex items-start gap-3">
                  <CheckCircle className="w-5 h-5 text-green-400 mt-1 flex-shrink-0" />
                  <div className="flex-1">
                    <div className="font-medium mb-1">{change.description}</div>
                    <div className="text-sm text-zinc-400">
                      {change.reasoning}
                    </div>
                    <div className="text-xs text-zinc-500 mt-2">
                      Score: {change.score_before} → {change.score_after}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="glass rounded-2xl p-8">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-2xl font-bold">Skill Changes</h3>
          <button
            onClick={() => setShowDiff(!showDiff)}
            className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 rounded-lg transition-colors"
          >
            {showDiff ? "Hide" : "Show"} Diff
          </button>
        </div>

        {showDiff && (
          <div className="bg-zinc-900 rounded-lg p-6 overflow-x-auto">
            <div className="font-mono text-sm space-y-1">
              {diff.map((part: Change, idx: number) => {
                const lines = part.value.split("\n").filter((l) => l.trim());
                return lines.map((line, lineIdx) => (
                  <div
                    key={`${idx}-${lineIdx}`}
                    className={`
                      px-2 py-1
                      ${part.added ? "bg-green-500/20 text-green-400" : ""}
                      ${part.removed ? "bg-red-500/20 text-red-400" : ""}
                      ${!part.added && !part.removed ? "text-zinc-400" : ""}
                    `}
                  >
                    {part.added && "+ "}
                    {part.removed && "- "}
                    {!part.added && !part.removed && "  "}
                    {line}
                  </div>
                ));
              })}
            </div>
          </div>
        )}
      </div>

      <div className="flex gap-4">
        <button
          onClick={handleDownload}
          className="flex-1 py-4 gradient-bg rounded-xl font-semibold hover:scale-105 transition-all flex items-center justify-center gap-2"
        >
          <Download className="w-5 h-5" />
          Download Improved Skill
        </button>

        <button
          onClick={onStartOver}
          className="flex-1 py-4 bg-zinc-800 hover:bg-zinc-700 rounded-xl font-semibold transition-all flex items-center justify-center gap-2"
        >
          <RotateCcw className="w-5 h-5" />
          Start Over
        </button>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { Loader2, StopCircle } from "lucide-react";

interface RunningStepProps {
  sessionId: string;
  apiKey: string;
  scenarios: any[];
  evals: any[];
  onComplete: (result: any) => void;
}

interface Experiment {
  experiment_id: number;
  description: string;
  status: string;
  score: number;
  max_score: number;
  pass_rate: number;
  per_eval: any[];
}

export default function RunningStep({
  sessionId,
  apiKey,
  scenarios,
  evals,
  onComplete,
}: RunningStepProps) {
  const [experiments, setExperiments] = useState<Experiment[]>([]);
  const [currentScore, setCurrentScore] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [currentExperiment, setCurrentExperiment] = useState<string>("");
  const [started, setStarted] = useState(false);

  useEffect(() => {
    if (!started) {
      setStarted(true);
      startOptimization();
    }
  }, []);

  const startOptimization = async () => {
    setIsRunning(true);
    const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891";

    try {
      // Start the optimization
      const startResponse = await fetch(
        `${API_BASE}/api/start/${sessionId}`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            gemini_api_key: apiKey,
            max_rounds: 20,
          }),
        }
      );

      if (!startResponse.ok) {
        const err = await startResponse.json().catch(() => ({}));
        if (!err.detail?.includes("already running")) {
          throw new Error(err.detail || "Failed to start optimization");
        }
      }

      // Poll for status every 3 seconds
      const poll = async () => {
        let lastExpCount = 0;
        while (true) {
          await new Promise((r) => setTimeout(r, 3000));

          try {
            const res = await fetch(`${API_BASE}/api/status/${sessionId}`);
            if (!res.ok) continue;
            const data = await res.json();

            // Update experiments if new ones arrived
            if (data.experiments && data.experiments.length > lastExpCount) {
              const newExps = data.experiments;
              setExperiments(newExps);
              const latest = newExps[newExps.length - 1];
              setCurrentScore(latest.pass_rate);
              setCurrentExperiment(
                latest.status === "baseline"
                  ? "Baseline complete"
                  : `Experiment ${latest.experiment_id}: ${latest.status}`
              );
              lastExpCount = newExps.length;
            }

            // Check if complete
            if (data.status === "complete" && data.final_result) {
              setIsRunning(false);
              onComplete(data.final_result);
              return;
            }

            if (data.status === "error") {
              setIsRunning(false);
              alert(`Error: ${data.error || "Unknown error"}`);
              return;
            }

            if (data.status === "stopped") {
              setIsRunning(false);
              return;
            }
          } catch {
            // Network error, keep polling
          }
        }
      };

      poll();
    } catch (error: any) {
      alert(error.message || "Failed to start optimization.");
      setIsRunning(false);
    }
  };

  const handleStop = async () => {
    try {
      const API_BASE2 = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891";
      await fetch(`${API_BASE2}/api/stop/${sessionId}`, {
        method: "POST",
      });
      setIsRunning(false);
    } catch (error) {
      alert("Failed to stop optimization");
    }
  };

  const chartData = experiments.map((exp) => ({
    experiment: exp.experiment_id === 0 ? "Base" : exp.experiment_id.toString(),
    passRate: exp.pass_rate,
    status: exp.status,
  }));

  const evalBreakdown = evals.map((evalItem) => {
    const latestExperiment = experiments[experiments.length - 1];
    if (!latestExperiment) {
      return { ...evalItem, passed: 0, total: 0, passRate: 0 };
    }

    const evalResult = latestExperiment.per_eval?.find(
      (pe: any) => pe.eval_id === evalItem.id
    );

    return {
      ...evalItem,
      passed: evalResult?.passed || 0,
      total: evalResult?.total || 0,
      passRate: evalResult?.pass_rate || 0,
    };
  });

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div className="glass rounded-2xl p-8">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-3xl font-bold mb-2">
              {currentScore.toFixed(1)}
              <span className="text-lg text-zinc-500">%</span>
            </h2>
            <p className="text-zinc-400">{currentExperiment}</p>
          </div>

          {isRunning && (
            <button
              onClick={handleStop}
              className="px-6 py-3 bg-red-500/20 hover:bg-red-500/30 text-red-400 rounded-xl transition-all flex items-center gap-2"
            >
              <StopCircle className="w-5 h-5" />
              Stop Optimization
            </button>
          )}
        </div>

        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#27272a" />
            <XAxis
              dataKey="experiment"
              stroke="#71717a"
              style={{ fontSize: "12px" }}
            />
            <YAxis
              stroke="#71717a"
              style={{ fontSize: "12px" }}
              domain={[0, 100]}
            />
            <Tooltip
              contentStyle={{
                backgroundColor: "#18181b",
                border: "1px solid #27272a",
                borderRadius: "8px",
              }}
            />
            <defs>
              <linearGradient id="colorGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3} />
                <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0} />
              </linearGradient>
            </defs>
            <Line
              type="monotone"
              dataKey="passRate"
              stroke="#8b5cf6"
              strokeWidth={3}
              dot={(props: any) => {
                const { cx, cy, payload, index } = props;
                const color =
                  payload.status === "baseline"
                    ? "#3b82f6"
                    : payload.status === "keep"
                    ? "#22c55e"
                    : "#ef4444";
                return <circle key={`dot-${index}`} cx={cx} cy={cy} r={5} fill={color} />;
              }}
              fill="url(#colorGradient)"
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="glass rounded-2xl p-8">
          <h3 className="text-xl font-bold mb-6">Experiment Log</h3>
          <div className="space-y-3 max-h-96 overflow-y-auto">
            {experiments.length === 0 ? (
              <div className="flex items-center justify-center py-12 text-zinc-500">
                <Loader2 className="w-8 h-8 animate-spin" />
              </div>
            ) : (
              experiments.map((exp) => (
                <div
                  key={exp.experiment_id}
                  className="p-4 bg-zinc-900 border border-zinc-800 rounded-lg"
                >
                  <div className="flex items-start justify-between mb-2">
                    <span
                      className={`
                      px-3 py-1 rounded-full text-xs font-medium
                      ${
                        exp.status === "baseline"
                          ? "bg-blue-500/20 text-blue-400"
                          : exp.status === "keep"
                          ? "bg-green-500/20 text-green-400"
                          : "bg-red-500/20 text-red-400"
                      }
                    `}
                    >
                      {exp.status === "baseline"
                        ? "Baseline"
                        : exp.status === "keep"
                        ? "Keep ✓"
                        : "Discard ✗"}
                    </span>
                    <span className="text-lg font-bold text-violet-400">
                      {exp.pass_rate}%
                    </span>
                  </div>
                  <p className="text-sm text-zinc-400">
                    {exp.experiment_id === 0
                      ? "Initial baseline"
                      : exp.description}
                  </p>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="glass rounded-2xl p-8">
          <h3 className="text-xl font-bold mb-6">Evaluation Breakdown</h3>
          <div className="space-y-4">
            {evalBreakdown.map((evalItem) => (
              <div key={evalItem.id}>
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium">{evalItem.name}</span>
                  <span className="text-sm text-zinc-400">
                    {evalItem.passed}/{evalItem.total}
                  </span>
                </div>
                <div className="w-full h-2 bg-zinc-800 rounded-full overflow-hidden">
                  <div
                    className="h-full gradient-bg transition-all duration-500"
                    style={{ width: `${evalItem.passRate}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Check } from "lucide-react";

interface StepIndicatorProps {
  currentStep: number;
}

const steps = [
  { number: 1, name: "Upload" },
  { number: 2, name: "Configure" },
  { number: 3, name: "Optimize" },
  { number: 4, name: "Results" },
];

export default function StepIndicator({ currentStep }: StepIndicatorProps) {
  return (
    <div className="flex items-center justify-center gap-4">
      {steps.map((step, index) => (
        <div key={step.number} className="flex items-center">
          <div className="flex items-center gap-3">
            <div
              className={`
                w-12 h-12 rounded-full flex items-center justify-center font-semibold
                transition-all duration-300
                ${
                  currentStep > step.number
                    ? "gradient-bg text-white"
                    : currentStep === step.number
                    ? "gradient-bg text-white scale-110"
                    : "bg-zinc-800 text-zinc-500"
                }
              `}
            >
              {currentStep > step.number ? (
                <Check className="w-6 h-6" />
              ) : (
                step.number
              )}
            </div>
            <span
              className={`
                text-sm font-medium transition-colors
                ${
                  currentStep >= step.number
                    ? "text-white"
                    : "text-zinc-500"
                }
              `}
            >
              {step.name}
            </span>
          </div>

          {index < steps.length - 1 && (
            <div
              className={`
                w-16 h-0.5 mx-4 transition-colors
                ${
                  currentStep > step.number
                    ? "bg-gradient-to-r from-violet-500 to-purple-500"
                    : "bg-zinc-800"
                }
              `}
            />
          )}
        </div>
      ))}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";

export default function ThemeToggle() {
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    const saved = localStorage.getItem("theme");
    if (saved === "light") {
      setIsDark(false);
      document.documentElement.classList.add("light");
      document.documentElement.classList.remove("dark");
    } else {
      setIsDark(true);
      document.documentElement.classList.add("dark");
      document.documentElement.classList.remove("light");
    }
  }, []);

  const toggle = () => {
    const next = !isDark;
    setIsDark(next);
    if (next) {
      document.documentElement.classList.add("dark");
      document.documentElement.classList.remove("light");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.add("light");
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
    }
  };

  return (
    <button
      onClick={toggle}
      className="fixed top-4 right-4 z-50 p-2 rounded-lg bg-zinc-200 dark:bg-zinc-800 hover:bg-zinc-300 dark:hover:bg-zinc-700 transition-colors border border-zinc-300 dark:border-zinc-700"
      aria-label="Toggle theme"
    >
      {isDark ? (
        <svg className="w-5 h-5 text-yellow-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
        </svg>
      ) : (
        <svg className="w-5 h-5 text-zinc-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
        </svg>
      )}
    </button>
  );
}

"use client";

import { useState, useRef } from "react";
import { Upload, FileText, Loader2, Sparkles, FolderOpen } from "lucide-react";

interface UploadStepProps {
  onComplete: (
    sessionId: string,
    apiKey: string,
    metadata: any,
    scenarios: any[],
    evals: any[]
  ) => void;
}

const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8891";

const EXAMPLE_SKILLS = [
  {
    name: "Code Reviewer",
    description: "Reviews code for security, performance, and best practices",
    path: "code-reviewer",
  },
  {
    name: "Content Writer",
    description: "Writes marketing copy for landing pages and emails",
    path: "content-writer",
  },
];

export default function UploadStep({ onComplete }: UploadStepProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [apiKey, setApiKey] = useState("");
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [fileList, setFileList] = useState<string[]>([]);
  const [metadata, setMetadata] = useState<any>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files);
    const zipFile = files.find((f) => f.name.endsWith(".zip"));
    if (zipFile) {
      await uploadZip(zipFile);
    } else if (files.length > 0) {
      await uploadMultipleFiles(files);
    }
  };

  const handleZipSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files[0]) {
      await uploadZip(files[0]);
    }
  };

  const handleFolderSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      await uploadMultipleFiles(Array.from(files));
    }
  };

  const uploadZip = async (file: File) => {
    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append("file", file);
      const response = await fetch(`${API_BASE}/api/upload`, {
        method: "POST",
        body: formData,
      });
      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.detail || "Upload failed");
      }
      const data = await response.json();
      setSessionId(data.session_id);
      setFileList(data.file_list);
      setMetadata(data.metadata);
    } catch (error: any) {
      alert(error.message || "Upload failed. Please try again.");
    } finally {
      setIsUploading(false);
    }
  };

  const uploadMultipleFiles = async (files: File[]) => {
    setIsUploading(true);
    try {
      const formData = new FormData();
      for (const f of files) {
        const path = (f as any).webkitRelativePath || f.name;
        formData.append("files", f, path);
      }
      const response = await fetch(`${API_BASE}/api/upload-files`, {
        method: "POST",
        body: formData,
      });
      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.detail || "Upload failed");
      }
      const data = await response.json();
      setSessionId(data.session_id);
      setFileList(data.file_list);
      setMetadata(data.metadata);
    } catch (error: any) {
      alert(error.message || "Upload failed. Please try again.");
    } finally {
      setIsUploading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!apiKey || !sessionId) return;
    setIsAnalyzing(true);
    try {
      const response = await fetch(`${API_BASE}/api/analyze`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: sessionId, gemini_api_key: apiKey }),
      });
      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.detail || "Analysis failed");
      }
      const data = await response.json();
      onComplete(sessionId, apiKey, metadata, data.scenarios, data.evals);
    } catch (error: any) {
      alert(error.message || "Analysis failed. Check your API key.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleExampleSelect = async (examplePath: string) => {
    if (!apiKey) {
      alert("Please enter your Google API key first.");
      return;
    }
    setIsUploading(true);
    try {
      const loadResponse = await fetch(`${API_BASE}/api/examples/${examplePath}/load`, {
        method: "POST",
      });
      if (!loadResponse.ok) throw new Error("Failed to load example");
      const loadData = await loadResponse.json();
      setSessionId(loadData.session_id);
      setFileList(loadData.file_list);
      setMetadata(loadData.metadata);
      setIsUploading(false);
      setIsAnalyzing(true);

      const analyzeResponse = await fetch(`${API_BASE}/api/analyze`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: loadData.session_id, gemini_api_key: apiKey }),
      });
      if (!analyzeResponse.ok) {
        const err = await analyzeResponse.json().catch(() => ({}));
        throw new Error(err.detail || "Analysis failed");
      }
      const analyzeData = await analyzeResponse.json();
      onComplete(loadData.session_id, apiKey, loadData.metadata, analyzeData.scenarios, analyzeData.evals);
    } catch (error: any) {
      alert(error.message || "Failed to load example skill.");
      setSessionId(null);
    } finally {
      setIsUploading(false);
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {!sessionId ? (
        <>
          <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`glass rounded-2xl p-16 text-center transition-all ${
              isDragging ? "border-violet-500 bg-violet-500/10 scale-105" : "border-zinc-800 hover:border-zinc-700"
            }`}
          >
            <input type="file" accept=".zip" onChange={handleZipSelect} className="hidden" id="zip-upload" />
            <input
              type="file"
              ref={folderInputRef}
              onChange={handleFolderSelect}
              className="hidden"
              id="folder-upload"
              {...({ webkitdirectory: "", directory: "" } as any)}
              multiple
            />

            <div className="mb-6">
              {isUploading ? (
                <Loader2 className="w-16 h-16 mx-auto text-violet-500 animate-spin" />
              ) : (
                <Upload className="w-16 h-16 mx-auto text-zinc-500" />
              )}
            </div>

            <h3 className="text-2xl font-semibold mb-2">
              {isUploading ? "Uploading..." : "Drop your skill here"}
            </h3>
            <p className="text-zinc-400 mb-4">Drag a .zip file or use the buttons below</p>

            <div className="flex justify-center gap-4">
              <label
                htmlFor="zip-upload"
                className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 rounded-xl cursor-pointer transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <Upload className="w-4 h-4" />
                Upload .zip
              </label>
              <button
                onClick={() => folderInputRef.current?.click()}
                className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 rounded-xl cursor-pointer transition-colors flex items-center gap-2 text-sm font-medium"
              >
                <FolderOpen className="w-4 h-4" />
                Upload Folder
              </button>
            </div>
          </div>

          <div className="glass rounded-2xl p-6">
            <label className="block">
              <span className="text-sm font-medium text-zinc-400 mb-2 block">Google API Key</span>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="Enter your Google API key"
                className="w-full px-4 py-3 bg-zinc-900 border border-zinc-800 rounded-lg focus:outline-none focus:border-violet-500 transition-colors"
              />
              <span className="text-xs text-zinc-500 mt-1 block">
                Required for analysis. Stored locally, sent only to the backend.
              </span>
            </label>
          </div>

          <div>
            <p className="text-center text-zinc-500 mb-4">
              {isAnalyzing ? "Analyzing with ADK agents..." : "Or try an example skill:"}
            </p>
            <div className="grid grid-cols-2 gap-4">
              {EXAMPLE_SKILLS.map((skill) => (
                <button
                  key={skill.path}
                  onClick={() => handleExampleSelect(skill.path)}
                  disabled={isUploading || isAnalyzing || !apiKey}
                  className={`glass rounded-xl p-6 text-left transition-all ${
                    apiKey && !isUploading && !isAnalyzing
                      ? "hover:border-violet-500 hover:scale-105 cursor-pointer"
                      : "opacity-50 cursor-not-allowed"
                  }`}
                >
                  <h4 className="font-semibold mb-2 flex items-center gap-2">
                    {skill.name}
                    {isAnalyzing && <Loader2 className="w-4 h-4 animate-spin text-violet-500" />}
                  </h4>
                  <p className="text-sm text-zinc-400">{skill.description}</p>
                </button>
              ))}
            </div>
          </div>
        </>
      ) : (
        <div className="space-y-6">
          <div className="glass rounded-2xl p-8">
            <div className="flex items-start gap-4 mb-6">
              <FileText className="w-8 h-8 text-violet-500" />
              <div className="flex-1">
                <h3 className="text-xl font-semibold mb-1">{metadata?.name || "Skill Uploaded"}</h3>
                {metadata?.description && <p className="text-zinc-400">{metadata.description}</p>}
              </div>
            </div>
            <div className="border-t border-zinc-800 pt-4 mt-4">
              <p className="text-sm text-zinc-500 mb-2">Files in skill:</p>
              <div className="flex flex-wrap gap-2">
                {fileList.map((file) => (
                  <span key={file} className="px-3 py-1 bg-zinc-800 rounded-full text-xs text-zinc-300">
                    {file}
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="glass rounded-2xl p-8">
            <label className="block mb-4">
              <span className="text-sm font-medium text-zinc-400 mb-2 block">Google API Key</span>
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="Enter your Google API key"
                className="w-full px-4 py-3 bg-zinc-900 border border-zinc-800 rounded-lg focus:outline-none focus:border-violet-500 transition-colors"
              />
            </label>
            <button
              onClick={handleAnalyze}
              disabled={!apiKey || isAnalyzing}
              className={`w-full py-4 rounded-xl font-semibold transition-all flex items-center justify-center gap-2 ${
                apiKey && !isAnalyzing ? "gradient-bg hover:scale-105" : "bg-zinc-800 text-zinc-500 cursor-not-allowed"
              }`}
            >
              {isAnalyzing ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Analyzing Skill...
                </>
              ) : (
                <>
                  <Sparkles className="w-5 h-5" />
                  Analyze Skill
                </>
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

